def norm(P):
 rmin=min(r for r,c in P); cmin=min(c for r,c in P)
 return frozenset((r-rmin,c-cmin) for r,c in P)
def transforms(P):
 out=[]
 for k in range(4):
  Q=P
  for _ in range(k): Q={(c,-r) for r,c in Q}
  for refl in [False,True]:
   R={(r,-c if refl else c) for r,c in Q}
   out.append((k,refl,norm(R)))
 return out
