def comps_color(arr,color,conn8=True):
 pts={(r,c) for r,row in enumerate(arr) for c,x in enumerate(row) if x==color}; out=[]
 while pts:
  stack=[pts.pop()]; comp=set(stack)
  while stack:
   r,c=stack.pop()
   for dr in [-1,0,1]:
    for dc in [-1,0,1]:
     if not (dr or dc):continue
     if not conn8 and abs(dr)+abs(dc)!=1:continue
     p=(r+dr,c+dc)
     if p in pts:pts.remove(p);comp.add(p);stack.append(p)
  out.append(comp)
 return out
